impl<V, F: Predicate<V>> OnceImpl<V, F> {
    pub closed spec fn inv(&self) -> F {
        self.f@
    }

    /// Creates a new uninitialized [`Once`].
    pub const fn new(Ghost(f): Ghost<F>) -> (r: Self)
        ensures
            r.wf(),
            r.inv() == f,
    {
        let (cell, Tracked(points_to)) = PCell::new(None);
        let tracked state = OnceState::Uninit(points_to);
        let state = vstd::atomic_ghost::AtomicU64::new(
            Ghost((cell, Ghost(f))),
            UNINIT,
            Tracked(state),
        );

        Self { cell, state, f: Ghost(f) }
    }

    /// Initializes the [`Once`] with the given value `v`.
    pub fn init(&self, v: V)
        requires
            self.inv().inv(v),
            self.wf(),
    {
        let cur_state =
            atomic_with_ghost! {
            &self.state => load(); ghost g => {}
        };

        if cur_state != UNINIT {
            return;
        } else {
            // Try to transition from UNINIT to OCCUPIED
            // We need to extract the PointsTo during this operation
            let tracked mut points_to = None;
            let res =
                atomic_with_ghost! {
                &self.state => compare_exchange(UNINIT, OCCUPIED);
                returning res; ghost g => {
                    // Extract the PointsTo from the Uninit state
                    match g {
                        OnceState::Uninit(pts) => {
                            // In the ghost block, we should be able to move pts since we're in proof context
                            points_to = Some(pts);
                        }
                        _ => {}
                    }
                }
            };

            if !res.is_err() {
                // Successfully transitioned to OCCUPIED state
                // Now we can safely initialize the cell with the extracted PointsTo
                let tracked mut points_to = points_to.tracked_unwrap();
                self.cell.replace(Tracked(&mut points_to), Some(v));

                // Extend the permission to static lifetime
                let tracked static_points_to = tracked_static_ref(points_to);

                // Transition to INITED state
                atomic_with_ghost! {
                    &self.state => store(INITED); ghost g => {
                        g = OnceState::Init(static_points_to);
                    }
                }
                return;
            } else {
                // Compare exchange failed, someone else is initializing
                // wait or abort.
                return;
            }
        }
    }

    /// Try to get the value stored in the [`Once`]. A [`Option::Some`]
    /// is returned if the cell is initialized; otherwise, [`Option::None`]
    /// is returned.
    pub fn get<'a>(&'a self) -> (r: Option<&'a V>)
        requires
            self.wf(),
        ensures
            self.wf(),
            r matches Some(res) ==> self.inv().inv(*res),
    {
        let res =
            atomic_with_ghost! {
            &self.state => load(); ghost g => {
                // No admit() needed
            }
        };

        if res == INITED {
            // We already have a &'static PointsTo in the Init state, so we can use it directly
            let tracked points_to_ref;
            atomic_with_ghost! {
                &self.state => no_op(); ghost g => {
                    match g {
                        OnceState::Init(pts) => {
                            points_to_ref = pts;  // pts is already &'static PointsTo
                        }
                        _ => {
                            proof_from_false::<()>();
                        }
                    }
                }
            };

            self.cell.borrow(Tracked(points_to_ref)).as_ref()
        } else {
            None
        }
    }
}

